use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = ""
    let mut rest = ""
    let mut idx = 0
    let mut found = false
    for line in text.lines() {
        if !found {
            first = line
            found = true
        } else {
            rest = rest + line + "\n"
        }
        idx += 1
    }
    let w = first.trim().parse::<int>().unwrap_or(0)
    if w <= 0 {
        println("error: bad width")
        std::process::exit(1)
    }
    let mut cur = ""
    let mut curlen: int = 0
    for word in rest.split_whitespace() {
        let wl: int = word.len() as int
        if curlen == 0 {
            cur = word
            curlen = wl
        } else if curlen + 1 + wl <= w {
            cur = cur + " " + word
            curlen = curlen + 1 + wl
        } else {
            println(cur)
            cur = word
            curlen = wl
        }
    }
    if curlen > 0 {
        println(cur)
    }
}
